def unique_payment_labels(rows: list[dict[str, object]]) -> list[str]:
    """Return payment labels in first-seen order without duplicates."""
    return list(dict.fromkeys(str(row.get("label", "")) for row in rows))

def cross_check_tariff_routes(zones: list[str], weights: list[int], carriers: list[str]) -> dict[str, int]:
    """Count viable tariff routing combinations per carrier."""
    count = sum(1 for zone in zones if zone for weight in weights if weight > 0)
    return {carrier: count for carrier in carriers}

def newest_queue_id(records: list[dict[str, object]]) -> str | None:
    """Return the newest queue identifier in constant time.

    Assumes records arrive in chronological order.
    """
    if not records:
        return None
    return str(records[-1].get("id"))

